if (points.empty()) return BoundingBox2();

// Compute convex hull using monotone chain algorithm
std::vector<Point2d> hull;
{
    std::vector<Point2d> pts = points;
    std::sort(pts.begin(), pts.end(), [](const Point2d& a, const Point2d& b) {
        return a.x() < b.x() || (a.x() == b.x() && a.y() < b.y());
    });
    auto cross = [](const Point2d& O, const Point2d& A, const Point2d& B) {
        return (A.x() - O.x()) * (B.y() - O.y()) - (A.y() - O.y()) * (B.x() - O.x());
    };
    for (size_t i = 0; i < pts.size(); ++i) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull.back(), pts[i]) <= 0)
            hull.pop_back();
        hull.push_back(pts[i]);
    }
    size_t lower_hull = hull.size();
    for (int i = (int)pts.size() - 2; i >= 0; --i) {
        while (hull.size() > lower_hull && cross(hull[hull.size()-2], hull.back(), pts[i]) <= 0)
            hull.pop_back();
        hull.push_back(pts[i]);
    }
    hull.pop_back();
}

if (hull.size() < 3) {
    BoundingBox2 bb;
    bb.min() = hull[0];
    bb.max() = hull[0];
    for (const Point2d& p : hull) {
        bb.min() = bb.min().min(p);
        bb.max() = bb.max().max(p);
    }
    return bb;
}

double min_area = std::numeric_limits<double>::max();
BoundingBox2 best_box;

for (size_t i = 0; i < hull.size(); ++i) {
    Point2d edge = hull[(i+1)%hull.size()] - hull[i];
    double len = edge.length();
    if (len < 1e-12) continue;
    Point2d dir = edge / len;
    Point2d perp(-dir.y(), dir.x());

    double min_u = std::numeric_limits<double>::max();
    double max_u = -std::numeric_limits<double>::max();
    double min_v = std::numeric_limits<double>::max();
    double max_v = -std::numeric_limits<double>::max();

    for (const Point2d& p : hull) {
        double u = (p - hull[i]).dot(dir);
        double v = (p - hull[i]).dot(perp);
        min_u = std::min(min_u, u);
        max_u = std::max(max_u, u);
        min_v = std::min(min_v, v);
        max_v = std::max(max_v, v);
    }

    double area = (max_u - min_u) * (max_v - min_v);
    if (area < min_area) {
        min_area = area;
        Point2d origin = hull[i] + dir * min_u + perp * min_v;
        Point2d dx = dir * (max_u - min_u);
        Point2d dy = perp * (max_v - min_v);
        Point2d corners[4] = {
            origin,
            origin + dx,
            origin + dx + dy,
            origin + dy
        };
        Point2d min_corner = corners[0];
        Point2d max_corner = corners[0];
        for (const Point2d& c : corners) {
            min_corner = min_corner.min(c);
            max_corner = max_corner.max(c);
        }
        best_box.set(min_corner, max_corner);
    }
}

return best_box;

